import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.PrintWriter;import java.util.Arrays;import java.util.StringTokenizer;public class Main {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));PrintWriter out = new PrintWriter(System.out);String line = br.readLine();if (line == null) return;int t = Integer.parseInt(line.trim());while (t-- > 0) {int n = Integer.parseInt(br.readLine().trim());long[] s = new long[n];StringTokenizer st = new StringTokenizer(br.readLine());for (int i = 0; i < n; i++) {s[i] = Long.parseLong(st.nextToken());}Arrays.sort(s);long minDiff = Long.MAX_VALUE;for (int i = 0; i < n - 1; i++) {long diff = s[i + 1] - s[i];if (diff < minDiff) {minDiff = diff;}}out.println(minDiff);}out.flush();out.close();}}